import { useMemo, useState } from 'react';
import { JxTable, JxBadge, JxPagination } from '@jinx-ui/react';

export interface User {
  id: string;
  name: string;
  role: string;
  status: 'active' | 'disabled';
}

interface UsersTableProps {
  users: User[];
}

const PAGE_SIZE = 10;

export default function UsersTable({ users }: UsersTableProps) {
  const [page, setPage] = useState(1);

  const pageCount = Math.max(1, Math.ceil(users.length / PAGE_SIZE));

  const pageUsers = useMemo(() => {
    const start = (page - 1) * PAGE_SIZE;
    return users.slice(start, start + PAGE_SIZE);
  }, [users, page]);

  return (
    <div className="jx-stack">
      <JxTable.Root>
        <JxTable.Header>
          <JxTable.Row>
            <JxTable.HeadCell>Имя</JxTable.HeadCell>
            <JxTable.HeadCell>Роль</JxTable.HeadCell>
            <JxTable.HeadCell>Статус</JxTable.HeadCell>
          </JxTable.Row>
        </JxTable.Header>
        <JxTable.Body>
          {pageUsers.map((user) => (
            <JxTable.Row key={user.id}>
              <JxTable.Cell>{user.name}</JxTable.Cell>
              <JxTable.Cell>{user.role}</JxTable.Cell>
              <JxTable.Cell>
                <JxBadge tone={user.status === 'active' ? 'success' : 'neutral'}>
                  {user.status === 'active' ? 'Активен' : 'Отключён'}
                </JxBadge>
              </JxTable.Cell>
            </JxTable.Row>
          ))}
        </JxTable.Body>
      </JxTable.Root>

      <JxPagination
        page={page}
        pageCount={pageCount}
        onPageChange={setPage}
      />
    </div>
  );
}

